Implement ResourceHooks in the Go SDK (#20002)
```go
func main() {
	pulumi.Run(func(ctx *pulumi.Context) error {
		hookFun := func(args *pulumi.ResourceHookArgs) error {
			ctx.Log.Info(fmt.Sprintf("Hook called with args=%+v\n", args), nil)
			return nil
		}
		hook, err := ctx.RegisterResourceHook("myhook", hookFun, &pulumi.ResourceHookOptions{
			OnDryRun: false,
		})
		if err != nil {
			return err
		}

		username, err := random.NewRandomPet(ctx,
			"username",
			&random.RandomPetArgs{},
			p

